<?php
require_once 'inc/db.php';require_once 'inc/auth.php';if((int)$_SESSION['role_id']!==1){http_response_code(403);die('Access denied.');}
$logs=$db->query('SELECT l.*,u.firstname,u.lastname FROM tbl_audit_logs l LEFT JOIN tbl_users u ON u.user_id=l.user_id ORDER BY l.created_at DESC LIMIT 250')->fetchAll(PDO::FETCH_ASSOC);$page_title='System Activity Logs';$breadcrumb='Security & governance';include 'inc/links.php';include 'inc/header.php';?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php';?><section role="main" class="content-body"><?php include 'inc/inner-header.php';?><div class="analytics-note security-note"><i class="fa fa-shield"></i><div><strong>System accountability</strong><span>Recent authentication, reporting, validation, and administration events are retained for security oversight.</span></div></div><section class="panel"><header class="panel-heading"><span class="panel-overline">Latest 250 events</span><h2 class="panel-title">Audit trail</h2></header><div class="panel-body table-responsive"><table class="table table-striped"><thead><tr><th>Date & time</th><th>User</th><th>Action</th><th>Details</th><th>IP address</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?php echo date('d M Y H:i:s',strtotime($l['created_at']));?></td><td><?php echo e(trim(($l['firstname']??'System').' '.($l['lastname']??'')));?></td><td><span class="event-pill"><?php echo e(str_replace('_',' ',$l['action']));?></span></td><td><?php echo e($l['details']);?></td><td><code><?php echo e($l['ip_address']);?></code></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="5" class="text-center text-muted">Activity will appear here as users operate the system.</td></tr><?php endif;?></tbody></table></div></section></section></div><?php include 'inc/scripts.php';?>
